def maximum_exp
  return minimum_exp_for_level(GrowthRate.max_level)
end

def add_exp(exp1, exp2)
  return (exp1 + exp2).clamp(0, maximum_exp)
end

def level=(value)
  if value < 1 || value > GameData::GrowthRate.max_level
    raise ArgumentError.new(_INTL("The level number ({1}) is invalid.", value))
  end
  @exp = growth_rate.minimum_exp_for_level(value)
  @level = value
end

def exp=(value)
  @exp = value
  @level = nil
end

def evYield
  this_evs = species_data.evs
  ret = {}
  GameData::Stat.each_main { |s| ret[s.id] = this_evs[s.id] }
  return ret
end

def learn_move(move_id)
  move_data = GameData::Move.try_get(move_id)
  return if !move_data
  # Check if self already knows the move; if so, move it to the end of the array
  @moves.each_with_index do |m, i|
    next if m.id != move_data.id
    @moves.push(m)
    @moves.delete_at(i)
    return
  end
  # Move is not already known; learn it
  @moves.push(Pokemon::Move.new(move_data.id))
  # Delete the first known move if self now knows more moves than it should
  @moves.shift if numMoves > MAX_MOVES
end

def record_first_moves
  clear_first_moves
  @moves.each { |m| @first_moves.push(m.id) }
end

def add_first_move(move_id)
  move_data = GameData::Move.try_get(move_id)
  @first_moves.push(move_data.id) if move_data && !@first_moves.include?(move_data.id)
end

def pbStartScreen(pkmn)
  moves = pbGetRelearnableMoves(pkmn)
  @scene.pbStartScene(pkmn, moves)
  loop do
    move = @scene.pbChooseMove
    if move
      if @scene.pbConfirm(_INTL("Teach {1}?", GameData::Move.get(move).name))
        if pbLearnMove(pkmn, move)
          $stats.moves_taught_by_reminder += 1
          @scene.pbEndScene
          return true
        end
      end
    elsif @scene.pbConfirm(_INTL("Give up trying to teach a new move to {1}?", pkmn.name))
      @scene.pbEndScene
      return false
    end
  end
end

def pbStartScene(pokemon, moves)
  @pokemon = pokemon
  @moves = moves
  moveCommands = []
  moves.each { |m| moveCommands.push(GameData::Move.get(m).name) }
  # Create sprite hash
  @viewport = Viewport.new(0, 0, Graphics.width, Graphics.height)
  @viewport.z = 99999
  @sprites = {}
  addBackgroundPlane(@sprites, "bg", "Move Reminder/bg", @viewport)
  @sprites["pokeicon"] = PokemonIconSprite.new(@pokemon, @viewport)
  @sprites["pokeicon"].setOffset(PictureOrigin::CENTER)
  @sprites["pokeicon"].x = 320
  @sprites["pokeicon"].y = 84
  @sprites["background"] = IconSprite.new(0, 0, @viewport)
  @sprites["background"].setBitmap("Graphics/UI/Move Reminder/cursor")
  @sprites["background"].y = 78
  @sprites["background"].src_rect = Rect.new(0, 72, 258, 72)
  @sprites["overlay"] = BitmapSprite.new(Graphics.width, Graphics.height, @viewport)
  pbSetSystemFont(@sprites["overlay"].bitmap)
  @sprites["commands"] = Window_CommandPokemon.new(moveCommands, 32)
  @sprites["commands"].height = 32 * (VISIBLEMOVES + 1)
  @sprites["commands"].visible = false
  @sprites["msgwindow"] = Window_AdvancedTextPokemon.new("")
  @sprites["msgwindow"].visible = false
  @sprites["msgwindow"].viewport = @viewport
  @typebitmap = AnimatedBitmap.new(_INTL("Graphics/UI/types"))
  pbDrawMoveList
  pbDeactivateWindows(@sprites)
  # Fade in all sprites
  pbFadeInAndShow(@sprites) { pbUpdate }
end

def self.triggerExpGainModifier(item, battler, exp)
  return trigger(ExpGainModifier, item, battler, exp, ret: -1)
end

Battle::ItemEffects::ExpGainModifier.add(:LUCKYEGG,
  proc { |item, battler, exp|
    next exp * 3 / 2
  }
)

Battle::ItemEffects::EVGainModifier.add(:MACHOBRACE,
  proc { |item, battler, evYield|
    evYield.each_key { |stat| evYield[stat] *= 2 }
  }
)

